"""Final append-only registered-output and lifecycle accounting; no native execution."""
import pathlib,sys,json
ROOT=pathlib.Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from protocol import read_json,write_new
RUN=ROOT/'_host/run';OUT=ROOT/'p1';rows=[json.loads(x) for x in (RUN/'LEDGER.jsonl').read_text().splitlines()];a=read_json(OUT/'ANALYSIS_P1.json');manifest=read_json(OUT/'ARCHIVE_MANIFEST.json');temp_bytes_per_restore=sum(x['bytes'] for x in manifest['files'] if x['path'].startswith('_host/run/') and len(x['path'].split('/'))>3)
def size(p):return sum(x.stat().st_size for x in p.rglob('*') if x.is_file()) if p.is_dir() else p.stat().st_size if p.exists() else 0
paths=[RUN,OUT,ROOT/'_host/P1_COMPLETE_CAS.zip',ROOT/'_host/P1_REMOTE_COMPLETE_CAS.zip',ROOT/'_host/p1_remote_readback'];current=sum(size(p) for p in paths);bound=current+2*temp_bytes_per_restore+1024**2;assert bound<4*1024**3
first=min(x['epoch'] for x in rows if x['event']=='PROCESS_ATTEMPT');last=max(x['epoch'] for x in rows if x['event']=='PROCESS_CLOSED');failed=[x for x in rows if x['event']=='PROCESS_CLOSED' and x['returncode']!=0]
